pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, uint256 blockNum) public {
        vm.assume(amount < 2**120); // keep amount reasonable for dealing
        vm.assume(blockNum > 0);
        vm.roll(blockNum);
        uint256 startTime = uint256(block.timestamp) + 1;
        vm.warp(startTime);
        address sender = address(0x1234);
        vm.deal(sender, amount);
        vm.prank(sender);
        bool ok;
        try c.fallback{value: amount}() { ok = true; } catch { ok = false; }
        uint256 newPast = c.pastBlockTime();
        bool receiverGotFunds = blockNum % 15 == 0;
        if (ok) {
            // call succeeded: pastBlockTime must be updated to the warped timestamp
            // unless the entire balance was transferred to sender (balance -> 0).
            // In the reference, success implies msg.value == 10 ether, so it must update.
            // In mutant, success with amount != 10 ether will NOT update pastBlockTime.
            bool noBalanceTransfer = !receiverGotFunds || address(c).balance > 0;
            if (noBalanceTransfer) {
                assertTrue(newPast == startTime);
            }
        } else {
            // call reverted: pastBlockTime must be unchanged (0 initially)
            assertTrue(newPast == 0);
        }
    }
}

