pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 blockNum, uint256 timestamp1, uint256 timestamp2) public {
        // Restrict timestamps to be strictly increasing and non-zero
        vm.assume(timestamp2 > timestamp1 && timestamp1 > 0);
        // Restrict block numbers to a reasonable range; keep wide enough to find both dividers
        blockNum = bound(blockNum, 1, 1000);

        address contributor = makeAddr("contributor");
        vm.deal(contributor, 20 ether);

        // Set block and timestamp for first contribution
        vm.roll(blockNum);
        vm.warp(timestamp1);
        vm.prank(contributor);
        c.f{value: 10 ether}();

        // Advance to a new block number and a strictly greater timestamp for second contribution
        vm.roll(blockNum + 1);
        vm.warp(timestamp2);
        vm.prank(contributor);
        (bool success,) = address(c).f{value: 10 ether}();
        require(success, "second contribution failed");

        // The property: the contract balance is zero iff block.number (of the second contribution) is divisible by 15
        uint256 balance = address(c).balance;
        if (blockNum + 1 % 15 == 0) {
            assertTrue(balance == 0);
        } else {
            assertTrue(balance > 0);
        }
    }
}

