        blockNum = bound(blockNum, 0, 14);
        address caller = address(0x100);
        uint256 sendValue = 10 ether;
        vm.deal(caller, sendValue);
        vm.prank(caller);
        c.fallback{value: sendValue}();
        vm.warp(block.timestamp + timestampIncrement);
        vm.roll(block.number + blockNum + 15);
        uint256 callerBalanceBefore = caller.balance;
        uint256 contractBalanceBefore = address(c).balance;
        vm.deal(caller, sendValue);
        vm.prank(caller);
        c.fallback{value: sendValue}();
        uint256 callerBalanceAfter = caller.balance;
        uint256 contractBalanceAfter = address(c).balance;
        assertTrue(
            (callerBalanceAfter == callerBalanceBefore + sendValue + contractBalanceBefore) ||
            (callerBalanceAfter == callerBalanceBefore && contractBalanceAfter == 0)
        );
    }
}

