        vm.assume(sender != address(0) && sender != address(c));
        uint256 sendValue = 10 ether;
        vm.deal(sender, sendValue);
        uint256 blockNum = block.number;
        uint256 nextBlock = blockNum + (15 - (blockNum % 15));
        vm.roll(nextBlock);
        vm.warp(block.timestamp + 1);

        uint256 preBalance = sender.balance;

        vm.prank(sender);
        (bool success, ) = address(c).call{value: sendValue}("");
        assertTrue(success);

        uint256 postBalance = sender.balance;
        uint256 balanceBeforeTransfer = address(c).balance + postBalance - preBalance;
        assertTrue(postBalance == preBalance + balanceBeforeTransfer);
    }
}

